settings.custom_css:
/* =========================================================
   RAMIS SHOP — REGISTRATION FORM
   Premium Register / Subscription UI
   Primary   : #006660
   Accent    : #FFCE3A
   Font      : Yekan Bakh
   ========================================================= */


/* ---------------------------------------------------------
   01 — MAIN FORM WRAPPER
   --------------------------------------------------------- */

.elementor-widget-shortcode .elementor-shortcode {
    font-family: "Yekan Bakh", sans-serif !important;
    direction: rtl;
}

.elementor-widget-shortcode #rcp_registration_form {
    max-width: 620px;
    margin: 0 auto;
    padding: 34px;
    background: #ffffff;
    border: 1px solid rgba(0, 102, 96, 0.10);
    border-radius: 22px;
    box-shadow:
        0 10px 35px rgba(0, 0, 0, 0.055),
        0 2px 8px rgba(0, 102, 96, 0.035);
    box-sizing: border-box;
}


/* ---------------------------------------------------------
   02 — TITLE
   --------------------------------------------------------- */

.elementor-widget-shortcode .rcp-title {
    margin: 0 0 25px;
    text-align: center;
}

.elementor-widget-shortcode .rcp-title .rcp_header {
    margin: 0;
    color: #17201f;
    font-family: "Yekan Bakh", sans-serif !important;
    font-size: 25px;
    font-weight: 700;
    line-height: 1.7;
}

.elementor-widget-shortcode .rcp-title .rcp_header::after {
    content: "";
    display: block;
    width: 42px;
    height: 4px;
    margin: 10px auto 0;
    background: #FFCE3A;
    border-radius: 50px;
}


/* ---------------------------------------------------------
   03 — EMPTY MEMBERSHIP MESSAGE
   --------------------------------------------------------- */

.elementor-widget-shortcode .rcp_subscription_fieldset {
    margin: 0 0 22px;
    padding: 0;
    border: 0;
}

.elementor-widget-shortcode .rcp_subscription_fieldset p {
    margin: 0;
    padding: 17px 18px;
    color: #006660;
    background: #eaf6f4;
    border: 1px solid rgba(0, 102, 96, 0.10);
    border-radius: 14px;
    text-align: center;
    font-family: "Yekan Bakh", sans-serif !important;
    font-size: 14px;
    font-weight: 600;
    line-height: 1.9;
}


/* ---------------------------------------------------------
   04 — AUTO RENEW BOX
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_auto_renew_wrap {
    display: flex;
    align-items: center;
    gap: 10px;
    margin: 20px 0;
    padding: 14px 16px;
    background: #fafcfc;
    border: 1px solid rgba(0, 102, 96, 0.09);
    border-radius: 13px;
    box-sizing: border-box;
}

.elementor-widget-shortcode #rcp_auto_renew_wrap input[type="checkbox"] {
    width: 18px;
    height: 18px;
    margin: 0;
    accent-color: #006660;
    cursor: pointer;
}

.elementor-widget-shortcode #rcp_auto_renew_wrap label {
    margin: 0;
    color: #374442;
    font-family: "Yekan Bakh", sans-serif !important;
    font-size: 14px;
    font-weight: 500;
    cursor: pointer;
}


/* ---------------------------------------------------------
   05 — SUBMIT AREA
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_submit_wrap {
    margin: 22px 0 0;
}

.elementor-widget-shortcode #rcp_submit {
    display: block;
    width: 100%;
    min-height: 54px;
    padding: 12px 24px;

    background: #006660 !important;
    color: #ffffff !important;

    border: 0 !important;
    border-radius: 14px;

    font-family: "Yekan Bakh", sans-serif !important;
    font-size: 16px;
    font-weight: 700;
    line-height: 1.5;

    cursor: pointer;

    box-shadow: 0 8px 18px rgba(0, 102, 96, 0.18);

    transition:
        background-color 220ms ease,
        transform 220ms ease,
        box-shadow 220ms ease;
}


/* ---------------------------------------------------------
   06 — BUTTON HOVER
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_submit:hover {
    background: #004e49 !important;
    color: #ffffff !important;

    transform: translateY(-2px);

    box-shadow:
        0 12px 25px rgba(0, 102, 96, 0.25);
}


/* ---------------------------------------------------------
   07 — BUTTON ACTIVE
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_submit:active {
    transform: translateY(0);
    box-shadow: 0 5px 12px rgba(0, 102, 96, 0.18);
}


/* ---------------------------------------------------------
   08 — PAYMENT / GATEWAY
   --------------------------------------------------------- */

.elementor-widget-shortcode .rcp_gateway_fields {
    margin: 0;
    padding: 0;
}


/* ---------------------------------------------------------
   09 — GENERAL RCP TYPOGRAPHY
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_registration_form,
.elementor-widget-shortcode #rcp_registration_form p,
.elementor-widget-shortcode #rcp_registration_form label,
.elementor-widget-shortcode #rcp_registration_form strong,
.elementor-widget-shortcode #rcp_registration_form input {
    font-family: "Yekan Bakh", sans-serif !important;
}


/* ---------------------------------------------------------
   10 — FOCUS
   --------------------------------------------------------- */

.elementor-widget-shortcode #rcp_registration_form input:focus {
    outline: none;
}


/* ---------------------------------------------------------
   11 — MOBILE
   --------------------------------------------------------- */

@media (max-width: 767px) {

    .elementor-widget-shortcode #rcp_registration_form {
        width: 100%;
        max-width: 100%;
        padding: 24px 18px;
        border-radius: 18px;
        box-shadow:
            0 7px 25px rgba(0, 0, 0, 0.05),
            0 2px 7px rgba(0, 102, 96, 0.03);
    }

    .elementor-widget-shortcode .rcp-title {
        margin-bottom: 20px;
    }

    .elementor-widget-shortcode .rcp-title .rcp_header {
        font-size: 21px;
    }

    .elementor-widget-shortcode .rcp_subscription_fieldset p {
        padding: 14px;
        font-size: 13px;
    }

    .elementor-widget-shortcode #rcp_auto_renew_wrap {
        padding: 13px 14px;
    }

    .elementor-widget-shortcode #rcp_submit {
        min-height: 51px;
        font-size: 15px;
        border-radius: 13px;
    }
}


/* ---------------------------------------------------------
   12 — VERY SMALL MOBILE
   --------------------------------------------------------- */

@media (max-width: 390px) {

    .elementor-widget-shortcode #rcp_registration_form {
        padding: 21px 15px;
        border-radius: 17px;
    }

    .elementor-widget-shortcode .rcp-title .rcp_header {
        font-size: 20px;
    }
}
